// Define the linear algebra error enum with attached message
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LinAlgError {
    NonConvergence(String),
    SingularMatrix(String),
    NonSquareMatrix(String),
    IncompatibleDimensions(String),
    InvalidInput(String),
    NumericalInstability(String),
    Other(String),
}

// Map an 8-bit error code and a message to a LinAlgError variant
pub fn select_error(error_variant: u8, message: String) -> LinAlgError {
    match error_variant {
        0 => LinAlgError::NonConvergence(message),
        1 => LinAlgError::SingularMatrix(message),
        2 => LinAlgError::NonSquareMatrix(message),
        3 => LinAlgError::IncompatibleDimensions(message),
        4 => LinAlgError::InvalidInput(message),
        5 => LinAlgError::NumericalInstability(message),
        _ => LinAlgError::Other(message),
    }
}

// Return Some(error) if condition is true, None otherwise.
// The error is constructed based on error_variant and message.
pub fn check_lin_alg_error(
    condition: bool,
    error_variant: u8,
    message: String,
) -> Option<LinAlgError> {
    if condition {
        Some(select_error(error_variant, message))
    } else {
        None
    }
}